CREATE QUEUE "requests" ( ID BIGINT NOT NULL , BODY TEXT NOT NULL );
CREATE TABLE "accepted" ( ID BIGINT PRIMARY KEY , BODY TEXT NOT NULL );
CREATE STREAM "events" ( ID BIGINT NOT NULL , BODY TEXT NOT NULL );
CREATE DATAFLOW "process" FROM QUEUE "requests" AS REQUEST AS BEGIN REQUIRE REQUEST . ID > 0 ELSE 'InvalidId' ; LET BODY = 'accepted:' || REQUEST . BODY ; BEGIN ATOMIC INSERT INTO "accepted" VALUES ( REQUEST . ID , BODY ) ON CONFLICT ( ID ) DO ASSERT SAME ROW ; REQUIRE REQUEST . BODY <> 'reject' ELSE 'RejectedBody' ; PRODUCE INTO "events" VALUES ( REQUEST . ID , BODY ) ; END ; END;
AUTHORIZE DATAFLOW "process" AS ROLE CURRENT_ROLE;
ACTIVATE DATAFLOW "process";
ENQUEUE INTO REQUESTS VALUES ( 7 , 'ready' ) , ( 0 , 'invalid' ) , ( 8 , 'reject' );
